#![forbid(unsafe_code)]
//! W03: ordered, staged event computation and bounded clock validation.
//!
//! Wire values are generated by core-types. These in-process capabilities do not
//! publish a new wire/storage protocol. Production clock publication, bootstrap
//! and asynchronous interpretation still need the contracts listed in
//! `tasks/requests/P5-08-runtime-publication.md`.

pub mod binding;
pub mod clock;
pub mod pipeline;
pub mod stages;
pub mod status;
pub mod store;
mod validation;

use core_types::{WireMessage, contract::Limits};

#[derive(Debug)]
pub enum Error {
    Contract(String),
    Rejected(&'static str),
    Clock(clock::ClockFault),
    Store(core_store::Error),
}
impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{self:?}")
    }
}
impl std::error::Error for Error {}
impl From<core_store::Error> for Error {
    fn from(value: core_store::Error) -> Self {
        Self::Store(value)
    }
}
pub type Result<T> = std::result::Result<T, Error>;
pub(crate) fn check(value: bool, why: &'static str) -> Result<()> {
    if value {
        Ok(())
    } else {
        Err(Error::Rejected(why))
    }
}
pub(crate) fn validate<T: WireMessage>(value: &T, limits: Limits) -> Result<()> {
    value
        .canonical_bytes(limits)
        .map(|_| ())
        .map_err(Error::Contract)
}
pub(crate) fn same<T: WireMessage>(a: &T, b: &T, limits: Limits) -> Result<bool> {
    Ok(a.canonical_bytes(limits).map_err(Error::Contract)?
        == b.canonical_bytes(limits).map_err(Error::Contract)?)
}
